function bytes(file) { return fs.readFileSync(file); }
function json(file) { return JSON.parse(bytes(file).toString("utf8")); }
function sha(value) { return crypto.createHash("sha256").update(value).digest("hex").toUpperCase(); }
function posix(value) { return path.resolve(value).split(path.sep).join("/"); }
function bind(file) { const value = bytes(file); return { absolute_path: posix(file), sha256: sha(value), bytes: value.length }; }
function stop(ok, code, detail) { if (!ok) throw Object.assign(new Error(`${code}: ${detail}`), { code }); }
function writeJson(relative, value) { const target = path.join(TASK_ROOT, relative); fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, `${JSON.stringify(value, null, 2)}\n`, "utf8"); }
function writeText(relative, value) { const target = path.join(TASK_ROOT, relative); fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, value.endsWith("\n") ? value : `${value}\n`, "utf8"); }
function listFiles(root) { const out = []; function visit(current) { for (const entry of fs.readdirSync(current, { withFileTypes: true })) { const target = path.join(current, entry.name); if (entry.isDirectory()) visit(target); else if (entry.isFile()) out.push(target); } } visit(root); return out; }
function digest(root) { const rows = listFiles(root).map((file) => ({ relative_path: path.relative(root, file).split(path.sep).join("/"), sha256: sha(bytes(file)), bytes: fs.statSync(file).size })).sort((a, b) => a.relative_path < b.relative_path ? -1 : a.relative_path > b.relative_path ? 1 : 0); const canonical = rows.map((x) => `${x.relative_path}|${x.sha256}|${x.bytes}`).join("\n"); return { file_count: rows.length, manifest_sha256: sha(Buffer.from(canonical, "utf8")) }; }
function names(root) { return fs.readdirSync(root, { withFileTypes: true }).filter((e) => e.isFile()).map((e) => e.name).sort(); }
function ref(relative) { const file = path.join(TASK_ROOT, relative); return { relative_path: relative, ...bind(file) }; }
function inputRef(relative) { const file = path.join(INPUT_ROOT, relative); return { relative_path: relative, ...bind(file) }; }

